+  interior:new THREE.MeshStandardMaterial({color:0x22242a,roughness:0.9}),
+};
+const brickMats=['#9c4a38','#a8553f','#8f4232','#b05a40'].map((c,i)=>new THREE.MeshStandardMaterial({map:brickTex(100+i*17,c),roughness:0.94,metalness:0.02}));
