+  const body=new CANNON.Body({mass,shape:new CANNON.Box(new CANNON.Vec3(sx/2,sy/2,sz/2)),
+    position:new CANNON.Vec3(x,y,z),material:matBody,linearDamping:opts.ld??0.01,angularDamping:opts.ad??0.05,
