+/* ---------- impact FX (visual only, seeded) ---------- */
+function buildDust(){
+  const N=260, pos=new Float32Array(N*3); dustVel=new Float32Array(N*3);
+  const geo=new THREE.BufferGeometry(); geo.setAttribute('position',new THREE.BufferAttribute(pos,3));
+  dust=new THREE.Points(geo,new THREE.PointsMaterial({color:0xcbb59a,size:0.16,transparent:true,opacity:0,depthWrite:false}));
+  dust.frustumCulled=false; dynGroup.add(dust);
+}
+function registerImpact(iv,pos){
+  if(impacted&&iv<6)return;
+  if(!impacted){impacted=true;shake=Math.min(0.5,iv*0.02);
+    const r=mulberry32(42); const p=dust.geometry.attributes.position.array;
+    for(let i=0;i<p.length;i+=3){
+      p[i]=pos.x+(r()-0.5)*1.2; p[i+1]=Math.max(0.1,pos.y+(r()-0.5)*1.4); p[i+2]=pos.z+(r()-0.5)*2.4;
+      dustVel[i]=2+r()*7; dustVel[i+1]=r()*4.5; dustVel[i+2]=(r()-0.5)*7;}
+    dust.geometry.attributes.position.needsUpdate=true; dustLife=1.6; dust.material.opacity=0.75;
+  } else shake=Math.max(shake,Math.min(0.3,iv*0.012));
+}
